-- FLL-TP-RHIZOM-2023 · coverage wave block 4a (2026-09-29): fields the test procedure prints but the worksheets never asked, plus the
-- equations that fill three derived fields (vessel area, scaling factor, total VTS thickness — the last one existed as a dead derived field).
-- 17 fields on FLLTP-RHZ-05/-09/-17/-20. Quotes read on the rendered PDF in-session 2026-09-29 (VA); printed page in source_anchor.
-- SAFETY: all new fields is_required = false; no gate, value or required-flag changes here — those are block 4b (sign-off).
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20260929230000_fll_tp_rhizom_fields_coverage_block4a.sql
-- Rollback: scripts/migrations/rollback-20260929230000_fll_tp_rhizom_fields_coverage_block4a.sql
BEGIN;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'widerlager_eingebaut', 'Widerlager (Polystyrolplatten) eingebaut', 'Abutment (polystyrene boards) installed', 'boolean', NULL, false, '§3.2; §5.3', 'Coverage block 4 (A-6 / B-1): "Bei starrten Werkstoffen (z. B. Gussasphalt) kann auf ein Widerlager verzichtet werden" — the dicke/material fields and the REQ-06 abutment term apply only when installed (4b, staged).', 'verified_against_standard', 'Das Widerlager besteht aus Polystyrolplatten, mit denen die Innenseite der Gefäße allseitig einlagig ausgekleidet werden. Dieses Widerlager soll eine Dehnung der zu prüfenden Werkstoffe durch den sich einstellenden Rhizomdruck der Testpflanzen ermöglichen. Bei starrten Werkstoffen (z. B. Gussasphalt) kann auf ein Widerlager verzichtet werden.', 'FLL-TP-Rhizom 2023 gedruckte S. 9; 14 — §3.2; §5.3', NULL, NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'widerlager_eingebaut') AND w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'widerlager_verzicht_begruendung', 'Begründung für den Verzicht auf das Widerlager (starrer Werkstoff, z. B. Gussasphalt)', 'Reason for omitting the abutment (rigid material, e.g. mastic asphalt)', 'text', NULL, false, '§3.2', 'Coverage block 4 (A-6): documents the printed exemption.', 'verified_against_standard', 'Das Widerlager besteht aus Polystyrolplatten, mit denen die Innenseite der Gefäße allseitig einlagig ausgekleidet werden. Dieses Widerlager soll eine Dehnung der zu prüfenden Werkstoffe durch den sich einstellenden Rhizomdruck der Testpflanzen ermöglichen. Bei starrten Werkstoffen (z. B. Gussasphalt) kann auf ein Widerlager verzichtet werden.', 'FLL-TP-Rhizom 2023 gedruckte S. 9 — §3.2', NULL, NULL, NULL, 'widerlager_eingebaut == false', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'widerlager_verzicht_begruendung') AND w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'kontrollgefaesse_wasserdicht', 'Kontrollgefäße wasserdicht ausgeführt', 'Control vessels made watertight', 'boolean', NULL, false, '§5.2', 'Coverage block 4 (A-23): "sind wasserdicht auszuführen" — REQ-06 term (4b, staged).', 'verified_against_standard', 'Die Kontrollgefäße sind wasserdicht auszuführen. Der Boden der Prüfgefäße muss über einen Wasserablauf verfügen, um Undichtigkeiten (und somit Beschädigungen der zu prüfenden Abdichtung) während der Prüfung feststellen zu können.', 'FLL-TP-Rhizom 2023 gedruckte S. 13 — §5.2', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'kontrollgefaesse_wasserdicht') AND w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'gefaess_flaeche_m2', 'Grundfläche je Gefäß (Innenmaß L × B)', 'Base area per vessel (inner L × W)', 'number', 'm²', false, '§5.2', 'Coverage block 4 (A-22 / B-3): output of FLLTP-RHZ-05-D1 = gefaess_innenmass_l_mm · gefaess_innenmass_b_mm / 1 000 000.', 'verified_against_standard', 'Die Gefäße müssen ein Innenmaß von mindestens 800 x 800 x 250 mm aufweisen (s. Abb. 1). Unter Berücksichtigung einbautechnischer Erfordernisse (z. B. bei Abdichtungen mit einer Dicke über rund 50 mm) kann es notwendig sein, größere Gefäße einzusetzen. Alle nachfolgenden Angaben (z. B. Düngung, Pflanzdichte), die sich auf dieses Mindestmaß beziehen, sind an die ggf. größer dimensionierten Gefäße anzupassen.', 'FLL-TP-Rhizom 2023 gedruckte S. 13 — §5.2', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'gefaess_flaeche_m2') AND w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'gefaess_skalierungsfaktor', 'Skalierungsfaktor gegenüber dem Mindestgefäß 800 × 800 mm (0,64 m²)', 'Scaling factor relative to the minimum vessel 800 × 800 mm (0.64 m²)', 'number', '-', false, '§5.2', 'Coverage block 4 (A-22 / B-3): output of FLLTP-RHZ-05-D2 = gefaess_flaeche_m2 / 0.64; "Alle nachfolgenden Angaben (z. B. Düngung, Pflanzdichte) … sind an die ggf. größer dimensionierten Gefäße anzupassen" — REQ-10 / REQ-14 read it (4b, staged).', 'verified_against_standard', 'Die Gefäße müssen ein Innenmaß von mindestens 800 x 800 x 250 mm aufweisen (s. Abb. 1). Unter Berücksichtigung einbautechnischer Erfordernisse (z. B. bei Abdichtungen mit einer Dicke über rund 50 mm) kann es notwendig sein, größere Gefäße einzusetzen. Alle nachfolgenden Angaben (z. B. Düngung, Pflanzdichte), die sich auf dieses Mindestmaß beziehen, sind an die ggf. größer dimensionierten Gefäße anzupassen.', 'FLL-TP-Rhizom 2023 gedruckte S. 13 — §5.2', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'gefaess_skalierungsfaktor') AND w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'standrohr_anzahl', 'Anzahl Standrohre je Gefäß', 'Number of standpipes per vessel', 'number', 'Stk', false, '§3.5', 'Coverage block 4 (A-9): "zwei eingelassene Rohre" — REQ-25 (4b, staged).', 'verified_against_standard', 'Durch zwei eingelassene Rohre (∅ 50 mm, Länge 200 mm) aus pflanzenverträglichen Werkstoffen (z. B. PE) wird in der Vegetationstragschicht die Kontrolle des Wasserstandes und der Wasserqualität sichergestellt.', 'FLL-TP-Rhizom 2023 gedruckte S. 9 — §3.5', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'standrohr_anzahl') AND w.code = 'FLLTP-RHZ-09' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'standrohr_laenge_mm', 'Standrohr — Länge', 'Standpipe — length', 'number', 'mm', false, '§3.5', 'Coverage block 4 (A-9): "Länge 200 mm" — REQ-25 (4b, staged); the diameter field standrohr_durchmesser_mm exists (required) but was never compared with 50 mm.', 'verified_against_standard', 'Durch zwei eingelassene Rohre (∅ 50 mm, Länge 200 mm) aus pflanzenverträglichen Werkstoffen (z. B. PE) wird in der Vegetationstragschicht die Kontrolle des Wasserstandes und der Wasserqualität sichergestellt.', 'FLL-TP-Rhizom 2023 gedruckte S. 9 — §3.5', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'standrohr_laenge_mm') AND w.code = 'FLLTP-RHZ-09' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'rueckstellprobe_vor_pruefung_datum', 'Rückstellprobe VOR der Untersuchung entnommen am', 'Retained sample taken BEFORE the test on', 'date', NULL, false, '§6', 'Coverage block 4 (A-36): "vor und nach der Untersuchung" — two events; the single boolean rueckstellproben_entnommen stays.', 'verified_against_standard', 'Von der Abdichtung ist vom Prüfinstitut vor und nach der Untersuchung eine Rückstellprobe zu nehmen. Das entnommene Teilstück muss zumindest eine Nahtstelle pro Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten und eine Fläche von mindestens 0,5 m² aufweisen. Die Rückstellprobe ist bei Temperaturen über 5 °C und unter 25 °C trocken und dunkel beim Prüfinstitut zu lagern. Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (s. Abschnitt 8). Stoffliche Unverträglichkeiten sind bei der Lagerung zu beachten.', 'FLL-TP-Rhizom 2023 gedruckte S. 16 — §6', NULL, NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'rueckstellprobe_vor_pruefung_datum') AND w.code = 'FLLTP-RHZ-17' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'rueckstellprobe_nach_pruefung_datum', 'Rückstellprobe NACH der Untersuchung (zum Ende der Prüfung) entnommen am', 'Retained sample taken AFTER the test (at the end) on', 'date', NULL, false, '§6; §8.2', 'Coverage block 4 (A-36).', 'verified_against_standard', 'Von der Abdichtung ist vom Prüfinstitut vor und nach der Untersuchung eine Rückstellprobe zu nehmen. Das entnommene Teilstück muss zumindest eine Nahtstelle pro Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten und eine Fläche von mindestens 0,5 m² aufweisen. Die Rückstellprobe ist bei Temperaturen über 5 °C und unter 25 °C trocken und dunkel beim Prüfinstitut zu lagern. Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (s. Abschnitt 8). Stoffliche Unverträglichkeiten sind bei der Lagerung zu beachten. — Von der untersuchten Abdichtung sind zum Ende der Prüfung Rückstellproben zu entnehmen, die das Ergebnis der Untersuchung dokumentieren. Die Proben sind gemäß Abschnitt 5 zu lagern.', 'FLL-TP-Rhizom 2023 gedruckte S. 16; 21 — §6; §8.2', NULL, NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'rueckstellprobe_nach_pruefung_datum') AND w.code = 'FLLTP-RHZ-17' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'rueckstellprobe_flaeche_m2', 'Rückstellprobe — Fläche des entnommenen Teilstücks', 'Retained sample — area of the piece taken', 'number', 'm²', false, '§6', 'Coverage block 4 (A-33): "mindestens 0,5 m²" — REQ-23 (4b, staged).', 'verified_against_standard', 'Von der Abdichtung ist vom Prüfinstitut vor und nach der Untersuchung eine Rückstellprobe zu nehmen. Das entnommene Teilstück muss zumindest eine Nahtstelle pro Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten und eine Fläche von mindestens 0,5 m² aufweisen. Die Rückstellprobe ist bei Temperaturen über 5 °C und unter 25 °C trocken und dunkel beim Prüfinstitut zu lagern. Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (s. Abschnitt 8). Stoffliche Unverträglichkeiten sind bei der Lagerung zu beachten.', 'FLL-TP-Rhizom 2023 gedruckte S. 16 — §6', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'rueckstellprobe_flaeche_m2') AND w.code = 'FLLTP-RHZ-17' AND s.code = 'FLL-TP-RHIZOM-2023';
