SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'rueckstellprobe_trocken_dunkel', 'Rückstellprobe trocken und dunkel beim Prüfinstitut gelagert', 'Retained sample stored dry and dark at the test institute', 'boolean', NULL, false, '§6', 'Coverage block 4 (A-34): REQ-23 (4b, staged).', 'verified_against_standard', 'Von der Abdichtung ist vom Prüfinstitut vor und nach der Untersuchung eine Rückstellprobe zu nehmen. Das entnommene Teilstück muss zumindest eine Nahtstelle pro Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten und eine Fläche von mindestens 0,5 m² aufweisen. Die Rückstellprobe ist bei Temperaturen über 5 °C und unter 25 °C trocken und dunkel beim Prüfinstitut zu lagern. Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (s. Abschnitt 8). Stoffliche Unverträglichkeiten sind bei der Lagerung zu beachten.', 'FLL-TP-Rhizom 2023 gedruckte S. 16 — §6', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'rueckstellprobe_trocken_dunkel') AND w.code = 'FLLTP-RHZ-17' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'rueckstellprobe_lagerung_bis', 'Rückstellprobe — Lagerung mindestens bis (≥ Gültigkeitsende des Prüfberichts)', 'Retained sample — stored at least until (≥ end of report validity)', 'date', NULL, false, '§6', 'Coverage block 4 (A-35): "Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen" — compare with bescheinigung_gueltig_bis (FLLTP-RHZ-21); no date gate staged (DSL date comparison not proven).', 'verified_against_standard', 'Von der Abdichtung ist vom Prüfinstitut vor und nach der Untersuchung eine Rückstellprobe zu nehmen. Das entnommene Teilstück muss zumindest eine Nahtstelle pro Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten und eine Fläche von mindestens 0,5 m² aufweisen. Die Rückstellprobe ist bei Temperaturen über 5 °C und unter 25 °C trocken und dunkel beim Prüfinstitut zu lagern. Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (s. Abschnitt 8). Stoffliche Unverträglichkeiten sind bei der Lagerung zu beachten.', 'FLL-TP-Rhizom 2023 gedruckte S. 16 — §6', NULL, NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'rueckstellprobe_lagerung_bis') AND w.code = 'FLLTP-RHZ-17' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'lagerung_unvertraeglichkeiten_beachtet', 'Stoffliche Unverträglichkeiten bei der Lagerung beachtet', 'Material incompatibilities observed during storage', 'boolean', NULL, false, '§6', 'Coverage block 4 (A-35): attestation, no gate.', 'verified_against_standard', 'Von der Abdichtung ist vom Prüfinstitut vor und nach der Untersuchung eine Rückstellprobe zu nehmen. Das entnommene Teilstück muss zumindest eine Nahtstelle pro Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten und eine Fläche von mindestens 0,5 m² aufweisen. Die Rückstellprobe ist bei Temperaturen über 5 °C und unter 25 °C trocken und dunkel beim Prüfinstitut zu lagern. Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (s. Abschnitt 8). Stoffliche Unverträglichkeiten sind bei der Lagerung zu beachten.', 'FLL-TP-Rhizom 2023 gedruckte S. 16 — §6', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'lagerung_unvertraeglichkeiten_beachtet') AND w.code = 'FLLTP-RHZ-17' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'verlaengerung_beantragt', 'Verlängerung der Gültigkeitsdauer beantragt (statt Erstausstellung)', 'Extension of the validity period applied for (instead of first issue)', 'boolean', NULL, false, '§9', 'Coverage block 4 (A-61 / B-4): guard of REQ-22 — the four extension conditions apply "jedoch nur wenn" an extension is sought; a first-issue report was blocked by them (4b, staged).', 'verified_against_standard', 'Durch eine Bestätigung des Prüfinstituts kann die Gültigkeitsdauer des Prüfberichts in Zeitabschnitten von 5 Jahren verlängert werden, jedoch nur wenn die Prüfgrundlagen in wesentlichen Punkten nicht geändert wurden; das geprüfte Produkt noch dem aktuellen Lieferprogramm des Antragstellers entspricht; erneut Rückstellmuster beim Prüfinstitut hinterlegt werden (s. Abschnitt 5); der Hersteller durch eidesstattliche Erklärung zusichert, dass das Produkt sowie deren Herstellung und Fügetechnik mit dem geprüften Produkt identisch sind.', 'FLL-TP-Rhizom 2023 gedruckte S. 22 — §9', NULL, NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verlaengerung_beantragt') AND w.code = 'FLLTP-RHZ-20' AND s.code = 'FLL-TP-RHIZOM-2023';
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'FLLTP-RHZ-05-D1', 'gefaess_flaeche_m2 = gefaess_innenmass_l_mm * gefaess_innenmass_b_mm / 1000000', ARRAY['gefaess_innenmass_l_mm','gefaess_innenmass_b_mm']::text[], 'gefaess_flaeche_m2', 'm²', '§5.2', 'Coverage block 4 (A-22): base area of the vessel from the inner dimensions.', 'verified_against_standard', 'Die Gefäße müssen ein Innenmaß von mindestens 800 x 800 x 250 mm aufweisen (s. Abb. 1). Unter Berücksichtigung einbautechnischer Erfordernisse (z. B. bei Abdichtungen mit einer Dicke über rund 50 mm) kann es notwendig sein, größere Gefäße einzusetzen. Alle nachfolgenden Angaben (z. B. Düngung, Pflanzdichte), die sich auf dieses Mindestmaß beziehen, sind an die ggf. größer dimensionierten Gefäße anzupassen.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'FLLTP-RHZ-05-D2', 'gefaess_skalierungsfaktor = gefaess_flaeche_m2 / 0.64', ARRAY['gefaess_flaeche_m2']::text[], 'gefaess_skalierungsfaktor', '-', '§5.2', 'Coverage block 4 (A-22): ratio to the printed minimum vessel 800 × 800 mm = 0,64 m²; 1,0 for the minimum vessel.', 'verified_against_standard', 'Die Gefäße müssen ein Innenmaß von mindestens 800 x 800 x 250 mm aufweisen (s. Abb. 1). Unter Berücksichtigung einbautechnischer Erfordernisse (z. B. bei Abdichtungen mit einer Dicke über rund 50 mm) kann es notwendig sein, größere Gefäße einzusetzen. Alle nachfolgenden Angaben (z. B. Düngung, Pflanzdichte), die sich auf dieses Mindestmaß beziehen, sind an die ggf. größer dimensionierten Gefäße anzupassen.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'FLLTP-RHZ-06-D1', 'vts_gesamt_dicke_mm = vts_untere_schicht_dicke_mm + vts_obere_schicht_dicke_mm', ARRAY['vts_untere_schicht_dicke_mm','vts_obere_schicht_dicke_mm']::text[], 'vts_gesamt_dicke_mm', 'mm', '§5.6; §7.1', 'Coverage block 4: fills the existing derived field vts_gesamt_dicke_mm (declared derived, no equation before); inputs live on FLLTP-RHZ-09 (cross-sheet). Printed total (170 ±10) mm → REQ-26 (4b, staged).', 'verified_against_standard', 'Der Substratbedarf beträgt bei der geforderten Schichtdicke von (170 ±10) mm ca. 110 l je Versuchsgefäß (800 x 800 mm).'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLTP-RHZ-06' AND s.code = 'FLL-TP-RHIZOM-2023'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
-- The existing derived field vts_gesamt_dicke_mm (FLLTP-RHZ-06, section D) gets the derived widget so it renders read-only like every other equation output.
UPDATE fields f SET widget = 'derived' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-06' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'vts_gesamt_dicke_mm' AND f.widget IS NULL;
COMMIT;
